input.content:
"""Decide which files in a project tree are excluded by its .packignore files.

This is a pure-Python reimplementation of `packignore`, the legacy exclusion
engine. docs/PACKIGNORE.md describes the original, but is incomplete; the
behaviour implemented here is the one `packignore` actually has:

- Lines are split with str.splitlines() and stripped of surrounding
  whitespace. Empty lines and lines starting with `;` are comments. `#` is
  NOT a comment character, and there is no escaping: `\\` and `[...]` are
  literal.
- A leading `!` negates the pattern (the rest is taken verbatim).
- Trailing `/`s make the pattern match directories only. If what remains
  contains a `/`, the pattern is anchored to the .packignore's directory
  (leading `/`s are dropped); otherwise it matches a name at any depth.
- `*` (or any run of `*`) matches within a segment and `?` matches one
  character. A whole segment `**` matches zero or more segments, including
  at the end, so `foo/**` also matches `foo` itself.
- Every path (directory or file) is evaluated top-down: the last matching
  rule decides, the rules of deeper .packignore files coming after those of
  shallower ones. With no matching rule a path inherits its parent's state;
  a file is also excluded by default if it has any executable bit set or its
  first line contains `@generated`.
- A .packignore is only read if its directory is not excluded.
"""

import os
import re
import stat

_PACKIGNORE = ".packignore"
_GENERATED = b"@generated"


def _segment_regex(seg):
    out = []
    for part in re.split(r"(\*+|\?)", seg):
        if not part:
            continue
        if part[0] == "*":
            out.append("[^/]*")
        elif part == "?":
            out.append("[^/]")
        else:
            out.append(re.escape(part))
    return "".join(out)


def _parse(text):
    """Return the rules in a .packignore as (regex, negate, dir_only) tuples."""
    rules = []
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        negate = line.startswith("!")
        if negate:
            line = line[1:]
        dir_only = line.endswith("/")
        line = line.rstrip("/")
        anchored = "/" in line
        line = line.lstrip("/")
        if not line:
            continue
        segs = []
        for seg in line.split("/"):
            if not (seg == "**" and segs and segs[-1] == "**"):
                segs.append(seg)
        if not anchored and segs != ["**"]:
            segs.insert(0, "**")
        if segs == ["**"]:
            regex = ".*"
        else:
            regex = ""
            last = len(segs) - 1
            for i, seg in enumerate(segs):
                if seg == "**":
                    if i == 0:
                        regex += "(?:.*/)?"
                    elif i == last:
