from concurrent.futures import ThreadPoolExecutor
spec=importlib.util.spec_from_file_location("ig","/work/repo/snapshot/ignore.py"); ig=importlib.util.module_from_spec(spec); spec.loader.exec_module(ig)
NAMES=['a','b','c','ab','a.txt','b.log','d','e','.packignore','#x',';x','!x','x y','.h','a\\b','[a]','foo','bar.c']
PATCH=['a','b','*','**','?','.','txt','/','!','#',';',' ','\\','[',']','d','e','x','c','-','log']
def rname(r): return r.choice(NAMES) if r.random()<0.8 else ''.join(r.choice('abcde.*?[]!#; ') for _ in range(r.randint(1,4))).strip() or 'z'
def rpat(r,names):
    k=r.random()
    if k<0.4:
        segs=[r.choice(names+['*','**','?','*.txt','a*','*b']) for _ in range(r.randint(1,3))]
        p='/'.join(segs)
        if r.random()<0.2: p='/'+p
        if r.random()<0.25: p+='/'
        if r.random()<0.3: p='!'+p
        return p
    return ''.join(r.choice(PATCH) for _ in range(r.randint(0,8)))
def gen(seed, root):
    r=random.Random(seed)
    files={}
    dirs=['']
    for _ in range(r.randint(1,25)):
        parent=r.choice(dirs)
        n=rname(r)
        p=(parent+'/'+n) if parent else n
        if any(p==f or p.startswith(f+'/') for f in files) or any(k.startswith(p+'/') for k in files) or p in dirs: continue
        if r.random()<0.35: dirs.append(p); continue
        files[p]=None
    used=list(set(x for p in list(files)+dirs for x in p.split('/') if x))
    for d in dirs:
        if r.random()<0.6:
            p=(d+'/.packignore') if d else '.packignore'
            if p in dirs or any(k.startswith(p+'/') for k in files): continue
            files[p]='\n'.join(rpat(r,used) for _ in range(r.randint(0,6)))
    for p,c in files.items():
        full=os.path.join(root,p)
        os.makedirs(os.path.dirname(full),exist_ok=True)
        if c is None:
            c=r.choice(['','x','@generated\n','a\n@generated','#@generated'])
        with open(full,'w') as f: f.write(c)
        os.chmod(full, 0o755 if r.random()<0.1 else 0o644)
    for d in dirs:
        os.makedirs(os.path.join(root,d),exist_ok=True)
def run(seed):
    root=tempfile.mkdtemp(prefix='fz')
    try:
        gen(seed,root)
        try:
            out=subprocess.run([sys.executable,'/work/repo/tools/packignore',root],capture_output=True,text=True)
            exp=sorted(l for l in out.stdout.splitlines() if l) if out.returncode==0 else 'ERR'
        except Exception as e: exp='ERR'
        try: got=ig.ignored_files(root)
        except Exception as e: got='ERR'
        if exp!=got:
            dump={}
            for dp,dn,fn in os.walk(root):
