            parts = rel.split("/")
            for i in range(len(parts) - 1):
                parent, child = "/".join(parts[:i]), "/".join(parts[:i + 1])
                if child not in tree:
                    tree[child] = ([], [])
                    tree[parent][0].append(child)
            tree["/".join(parts[:-1])][1].append((rel, full, stat.S_IMODE(os.stat(full).st_mode)))
    return tree


