        if not excluded:
            sub = d + "/" + _PACKIGNORE if d else _PACKIGNORE
            if sub in tree:
                # packignore fails on a .packignore it cannot read.
                raise IsADirectoryError(f"{sub} is a directory")
            for rel, full, _ in files:
                if rel.rpartition("/")[2] == _PACKIGNORE:
                    with open(full, "rb") as f:
