import tarfile
import unicodedata

from ._unicode16 import ASSIGNED_SINCE_14, CASEFOLD_SINCE_14, DECOMPOSITION_SINCE_14

_PACKIGNORE = ".packignore"
_GENERATED = b"@generated"
_MAX_DOUBLE_STAR = 3
_MAX_FILES = 5000
_MAX_DEPTH = 64
_MAX_PATH_BYTES = 955
_MAX_UPLOAD_BYTES = 20_000_000


class PackignoreError(Exception):
    """The tree is one that `packignore` refuses or fails on."""


# --- patterns -------------------------------------------------------------


def _segment_regex(seg):
    out = []
    for part in re.split(r"(\*+|\?)", seg):
        if not part:
            continue
        if part[0] == "*":
            out.append(".*")
        elif part == "?":
            out.append(".")
        else:
            out.append(re.escape(part))
    return re.compile("".join(out), re.DOTALL)


def _parse(text):
    """Return the rules in a .packignore as (match, negate, dir_only, weight) tuples.

    `match` takes a path relative to the .packignore's directory, as a tuple
    of segments.
    """
    rules = []
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        negate = line.startswith("!")
        if negate:
            line = line[1:]
        dir_only = line.endswith("/")
        line = line.rstrip("/")
        anchored = "/" in line
        line = line.lstrip("/")
        if not line:
            continue
        if anchored:
            match = _anchored([None if seg == "**" else _segment_regex(seg)
                               for seg in line.split("/")])
        else:
            match = _unanchored(_segment_regex(line))
        weight = len(line) - sum(line.count(c) for c in "/*?")
        rules.append((match, negate, dir_only, weight))
    return rules


def _unanchored(regex):
    return lambda parts: regex.fullmatch(parts[-1]) is not None


def _anchored(segs):
    def match(parts):
        n = len(parts)
        states = {0}
        for seg in segs:
            if seg is None:
                states = {i + k for i in states for k in range(_MAX_DOUBLE_STAR + 1) if i + k <= n}
            else:
                states = {i + 1 for i in states if i < n and seg.fullmatch(parts[i])}
            if not states:
                return False
        return n in states
    return match


def _decide(parts, is_dir, rulesets):
    """Return True/False if a rule excludes/includes the path, else None."""
    result = None
    for depth, rules in rulesets:
        rel = parts[depth:]
        best = -1
        for match, negate, dir_only, weight in rules:
            if weight >= best and (is_dir or not dir_only) and match(rel):
                best, result = weight, not negate
    return result


# --- the tree as packignore sees it ----------------------------------------


def _assigned(cp):
    i = bisect.bisect_right(ASSIGNED_SINCE_14, (cp, 0x110000)) - 1
    if i >= 0 and ASSIGNED_SINCE_14[i][0] <= cp <= ASSIGNED_SINCE_14[i][1]:
        return True
    return unicodedata.category(chr(cp)) not in ("Cn", "Cs")


def _nfd(s):
    s = "".join(DECOMPOSITION_SINCE_14.get(c, c) for c in s)
    return unicodedata.normalize("NFD", s)


def _fold_key(name):
    """Unicode canonical caseless matching key: NFD(casefold(NFD(name)))."""
    return _nfd("".join(CASEFOLD_SINCE_14.get(c, c) for c in _nfd(name)).casefold())


class _Dir:
    __slots__ = ("parts", "dirs", "files")

    def __init__(self, parts):
        self.parts = parts
        self.dirs = {}   # fold key -> _Dir
        self.files = {}  # fold key -> [name, full path, mode]


def _first_line_has_marker(full):
    tail = b""
    with open(full, "rb") as f:
        while True:
            chunk = f.read(1 << 16)
            if not chunk:
                return False
            line, nl, _ = chunk.partition(b"\n")
            if _GENERATED in tail + line:
                return True
            if nl:
                return False
            tail = line[-(len(_GENERATED) - 1):]


def _walk(root):
    """Yield (relative path, full path) for the regular files under root,
    in the order the packignore client uploads them."""
    for dirpath, dirnames, filenames in os.walk(root):
        if os.path.samefile(dirpath, root) and ".git" in dirnames:
            dirnames.remove(".git")
        for name in filenames:
            full = os.path.join(dirpath, name)
            if os.path.islink(full) or not os.path.isfile(full):
                continue
            yield os.path.relpath(full, root).replace(os.sep, "/"), full


def _upload_size(entries):
    """Size of the gzipped tar the packignore client would upload."""
    class Counter:
        size = 0

        def write(self, data):
            self.size += len(data)

    out = Counter()
    with tarfile.open(fileobj=out, mode="w:gz") as tar:
        for rel, full in entries:
            info = tar.gettarinfo(full, arcname=rel)
            info.type = tarfile.REGTYPE
            info.linkname = ""
            with open(full, "rb") as f:
                tar.addfile(info, f)
    return out.size


def _check_upload_size(entries):
    # Cheap upper bound on the compressed size first; gzip never grows data
    # by more than a few bytes per 16 KiB.
    bound = 20480
    for rel, full in entries:
        bound += os.stat(full).st_size + 4096 + 6 * len(rel)
    if bound * 1.001 + 4096 > _MAX_UPLOAD_BYTES and _upload_size(entries) > _MAX_UPLOAD_BYTES:
        raise PackignoreError("request too large")


def _load(root):
    entries = list(_walk(root))
    _check_upload_size(entries)
    if len(entries) > _MAX_FILES:
        raise PackignoreError(f"too many files (limit {_MAX_FILES})")
    top = _Dir(())
    for rel, full in entries:
        parts = rel.split("/")
        if len(parts) > _MAX_DEPTH:
            raise PackignoreError(f"path too deep (limit {_MAX_DEPTH} levels)")
        try:
            size = len(rel.encode("utf-8"))
        except UnicodeEncodeError:
            raise PackignoreError(f"{rel!r}: name is not valid UTF-8") from None
        if size > _MAX_PATH_BYTES:
            raise PackignoreError(f"{rel!r}: path too long")
        for c in rel:
            if not _assigned(ord(c)):
                raise PackignoreError(f"{rel!r}: unassigned code point U+{ord(c):04X}")
        d = top
        for name in parts[:-1]:
            key = _fold_key(name)
            if key in d.files:
                raise PackignoreError(f"{rel!r}: file and directory collide")
            if key not in d.dirs:
                d.dirs[key] = _Dir(d.parts + (name,))
            d = d.dirs[key]
        key = _fold_key(parts[-1])
        if key in d.dirs:
            raise PackignoreError(f"{rel!r}: file and directory collide")
        mode = stat.S_IMODE(os.stat(full).st_mode)
        if key in d.files:
            d.files[key][1:] = [full, mode]
        else:
            d.files[key] = [parts[-1], full, mode]
    return top


# --- entry point --------------------------------------------------------------


def ignored_files(root):
    """Return the files under `root` that its .packignore files exclude.

    Paths are relative to `root`, use "/" as the separator, and are sorted.
    Only files are listed, never directories. A `.git` directory directly
    under `root` is skipped. Raises PackignoreError for trees `packignore`
    cannot handle.
    """
    ignored = []
    stack = [(_load(root), False, [])]
    while stack:
        d, excluded, rulesets = stack.pop()
        if not excluded:
            if any(sub.parts[-1] == _PACKIGNORE for sub in d.dirs.values()):
                raise PackignoreError("/".join(d.parts + (_PACKIGNORE,)) + " is a directory")
            for name, full, _ in d.files.values():
                if name == _PACKIGNORE:
                    with open(full, "rb") as f:
                        data = f.read()
                    try:
                        text = data.decode("utf-8")
                    except UnicodeDecodeError:
                        raise PackignoreError(
                            "/".join(d.parts + (name,)) + " is not valid UTF-8") from None
                    rulesets = rulesets + [(len(d.parts), _parse(text))]
        for name, full, mode in d.files.values():
            parts = d.parts + (name,)
            decision = _decide(parts, False, rulesets)
            if decision is None:
                decision = excluded or mode & 0o111 or _first_line_has_marker(full)
            if decision:
                ignored.append("/".join(parts))
        for sub in d.dirs.values():
            decision = _decide(sub.parts, True, rulesets)
            stack.append((sub, excluded if decision is None else decision, rulesets))
    # packignore reports one path per line.
    return sorted(line for path in ignored for line in path.splitlines() if line)

