        d, excluded, rulesets = stack.pop()
        subdirs, files = tree[d]
        if not excluded:
            if d + (_PACKIGNORE,) in tree:
                # packignore fails on a .packignore it cannot read.
                raise IsADirectoryError("/".join(d + (_PACKIGNORE,)) + " is a directory")
            for parts, full, _ in files:
                if parts[-1] == _PACKIGNORE:
                    with open(full, "rb") as f:
                        rulesets = rulesets + [(len(d), _parse(f.read().decode("utf-8")))]
                    break
        for parts, full, mode in files:
            decision = _decide(parts, False, rulesets)
            if decision is None:
                decision = excluded or _hidden(full, mode)
            if decision:
                ignored.append("/".join(parts))
        for sub in subdirs:
            decision = _decide(sub, True, rulesets)
            stack.append((sub, excluded if decision is None else decision, rulesets))
    # packignore reports one path per line.
    return sorted(line for path in ignored for line in path.splitlines() if line)
